using System;using System.Linq;using System.IO;using System.Text.Json;using System.Collections.Generic;using Deception.Core;using Deception.PolyModAdapter;
using U=Polytopia.Data.UnitData;using T=Polytopia.Data.TerrainData;using I=Polytopia.Data.ImprovementData;
namespace Deception.Tests{
 public static class MovementTests{
  static int Cases,Assertions;static void Check(bool b,string why){Assertions++;if(!b)throw new Exception(why);}static void Test(string n,Action f){try{f();Cases++;}catch(Exception e){throw new Exception(n,e);}}
  static LedgerAppearance Appearance(string form)=>new(form,new("imperius","default"),new("imperius","default"),new("imperius","default"),5,100,100,false,ApparentConcealment.Visible,-1,Array.Empty<string>());
  static LedgerUnit Row(GameState s)=>NativeRegroupSession.ReadIdentity(s,1)!;
  static void Change(GameState s,Func<LedgerUnit,LedgerUnit> edit){var snap=NativeGameStateEnvelope.Get(s)!;var l=NativeIdentityLedgerCodec.Decode(snap.Bytes(),snap.Revision);NativeGameStateEnvelope.Set(s,snap.Revision,NativeIdentityLedgerCodec.Encode(l with{Units=new[]{edit(l.Units[0])}},snap.Revision));}
  static (GameState,UnitState,MoveAction) Start(string actual="warrior",string apparent="warrior",int steps=1){
   NativeDisguiseMovement.Clear();NativeMimicWaterMovement.Clear();NativeApparentTerrain.Clear();NativeApparentTerrain.PendingDisguiseShed=NativeDisguiseMovement.IsShedding;NativeRegroupSession.Enabled=true;NativeRegroupSession.Faults=0;NativeRegroupSession.Reads=0;RecruitmentHooks.Registered=true;NativeLedgerState.Fail=false;PathFinder.Profiles.Clear();PathFinder.CheckedEdges.Clear();PathFinder.CostCalls=0;PathFinder.ThrowCost=false;
   var s=new GameState();foreach(U.Type t in Enum.GetValues<U.Type>())s.GameLogicData.Forms[t.ToString()]=new(){type=t,Movement=t is U.Type.knight?3:t is U.Type.rider or U.Type.firedragon or U.Type.shark?2:1,Fly=t==U.Type.firedragon,Swim=t is U.Type.island or U.Type.shark,Vehicle=t is U.Type.transportship or U.Type.cloak_boat,Wetland=t==U.Type.island};
   var u=new UnitState{type=Enum.Parse<U.Type>(actual),UnitData=s.GameLogicData.Forms[actual],health=70,coordinates=new(0,0),moved=true};s.Units[1]=u;
   var a=new MoveAction();for(int i=0;i<=steps;i++){var p=new WorldCoordinates(i,0);s.Map.Tiles[p]=new(){coordinates=p,unit=i==0?u:null};a.Path.Insert(0,p);}s.ActionStack.Add(a);
   var ledger=new NativeIdentityLedger(Guid.Parse("6f1c624c-c3a9-4a86-8d9e-dcf4245a0885"),2,1,new[]{new LedgerUnit(1,1,true,LedgerActualKind.Genuine,true,Appearance(apparent),PaidInvestmentKind.Known,8)},Array.Empty<LedgerReceipt>());NativeGameStateEnvelope.Set(s,0,NativeIdentityLedgerCodec.Encode(ledger,0));return(s,u,a);
  }
  static void Expected(GameState s,UnitState u,MoveAction a,bool shed){var effects=u.effects;int hp=u.health;var type=u.type;bool moved=u.moved,attacked=u.attacked;var cargo=u.passengerUnit;var data=u.UnitData;a.Execute(s);
   Check(Row(s).Independent!=shed,"wrong retained appearance");Check(Row(s).PaidStars==8&&Row(s).LogicalId==1,"identity/investment changed");Check(u.health==hp&&u.type==type&&u.moved==moved&&u.attacked==attacked&&ReferenceEquals(cargo,u.passengerUnit)&&ReferenceEquals(data,u.UnitData),"actual body/budget mutated");Check(a.Pending==shed&&a.Passives==(shed?0:1),"pending terrain suppression mismatch");Check(!NativeDisguiseMovement.IsShedding(s,u),"pending scope leaked");if(shed)Check(Row(s).Appearance is null,"visible projection still has false form");}
  public static int Run(){try{
   Test("one native reference hook and ABI guard",()=>{var h=new HarmonyLib.Harmony();NativeDisguiseMovement.Install(h);Check(h.Hooks.Count==1&&h.Hooks[0].DeclaringType==typeof(MoveAction),"wrong hook");try{Native.RequireHookAbi(typeof(PathFinder).GetMethod("IsTileAccessible")!);throw new Exception("unsafe hook allowed");}catch(NotSupportedException){}Check(typeof(NativeDisguiseMovement).GetMethod("BeforeMove")!.GetCustomAttributes(typeof(HarmonyLib.HarmonyPriority),false).Length==1,"prefix ordering missing");});
   Test("same form ordinary move",()=>{var(s,u,a)=Start();Expected(s,u,a,false);Check(PathFinder.Profiles.All(p=>!ReferenceEquals(p,u)&&p.type==U.Type.warrior),"profile aliases real body");});
   Test("already moved flag does not forbid accepted move",()=>{var(s,u,a)=Start();u.moved=true;u.attacked=true;Expected(s,u,a,false);});
   Test("fast real unit outruns slow mask",()=>{var(s,u,a)=Start("knight","warrior",2);Expected(s,u,a,true);});
   Test("fast mask can follow",()=>{var(s,u,a)=Start("knight","rider",2);Expected(s,u,a,false);Check(PathFinder.CheckedEdges.SequenceEqual(new[]{(new WorldCoordinates(0,0),new WorldCoordinates(1,0)),(new WorldCoordinates(1,0),new WorldCoordinates(2,0))}),"route edges reversed");});
   foreach(int cost in new[]{11,20,1000})Test("native final cost overshoot "+cost,()=>{var(s,u,a)=Start();s.Map.Tiles[a.Path[0]].Cost=cost;Expected(s,u,a,false);});
   foreach(int cost in new[]{10,1000})Test("cannot continue exhausted mask budget "+cost,()=>{var(s,u,a)=Start("knight","warrior",2);s.Map.Tiles[a.Path[1]].Cost=cost;Expected(s,u,a,true);});
   foreach(string[] effects in new[]{new[]{"Frozen"},new[]{"Frozen","Petrified"},new[]{"Petrified"}})Test("native apparent incapacity "+string.Join("+",effects),()=>{var(s,u,a)=Start();Change(s,r=>r with{Appearance=r.Appearance! with{Effects=effects}});Expected(s,u,a,effects.Contains("Frozen"));Check(u.effects.Count==0,"fake freeze affected real body");});
   Test("apparent Boosted movement only",()=>{var(s,u,a)=Start("knight","warrior",2);Change(s,r=>r with{Appearance=r.Appearance! with{Effects=new[]{"Boosted"}}});Expected(s,u,a,false);Check(u.effects.Count==0,"false boost became real");});
   foreach(string effect in new[]{"Swift","Bubble"})Test("native apparent speed effect "+effect,()=>{var(s,u,a)=Start("knight","warrior",2);Change(s,r=>r with{Appearance=r.Appearance! with{Effects=new[]{effect}}});Expected(s,u,a,false);});
   Test("native apparent poison speed penalty",()=>{var(s,u,a)=Start("knight","knight",3);Change(s,r=>r with{Appearance=r.Appearance! with{Effects=new[]{"Poisoned"}}});Expected(s,u,a,true);});
   foreach(bool port in new[]{false,true})Test("flying actual cannot hypothetically embark land mask "+port,()=>{var(s,u,a)=Start("firedragon","warrior");s.Map.Tiles[a.Path[0]].terrain=T.Type.Water;if(port)s.Map.Tiles[a.Path[0]].improvement=new(){type=I.Type.Port};Expected(s,u,a,true);});
   Test("real port embark preserves land passenger mask",()=>{var(s,u,a)=Start();s.Map.Tiles[a.Path[0]].terrain=T.Type.Water;s.Map.Tiles[a.Path[0]].improvement=new(){type=I.Type.Port};s.Map.Tiles[a.Path[0]].Cost=1000;Expected(s,u,a,false);});
   Test("real embark can keep native flying mask",()=>{var(s,u,a)=Start("warrior","firedragon");s.Map.Tiles[a.Path[0]].terrain=T.Type.Water;s.Map.Tiles[a.Path[0]].improvement=new(){type=I.Type.Port};Expected(s,u,a,false);});
   foreach(string form in new[]{"shark","island"})Test("aquatic mask onto land "+form,()=>{var(s,u,a)=Start("firedragon",form);s.Map.Tiles[a.Path[^1]].terrain=T.Type.Water;Expected(s,u,a,true);});
   Test("legal actual landing preserves vessel passenger",()=>{var(s,u,a)=Start("transportship","transportship");s.Map.Tiles[a.Path[^1]].terrain=T.Type.Water;u.passengerUnit=new(){id=2,type=U.Type.warrior,UnitData=s.GameLogicData.Forms["warrior"]};Change(s,r=>r with{Transport=new(2),Appearance=r.Appearance! with{Passenger=Appearance("rider")}});Expected(s,u,a,false);Check(PathFinder.Profiles[0].passengerUnit!.type==U.Type.rider&&!ReferenceEquals(PathFinder.Profiles[0].passengerUnit,u.passengerUnit),"cargo is not independent clone");});
   Test("real landing sheds nonlanding Shark",()=>{var(s,u,a)=Start("transportship","shark");s.Map.Tiles[a.Path[^1]].terrain=T.Type.Water;Expected(s,u,a,true);});
   Test("real landing keeps flying apparent root",()=>{var(s,u,a)=Start("transportship","firedragon");s.Map.Tiles[a.Path[^1]].terrain=T.Type.Water;Expected(s,u,a,false);});
   Test("apparent landing alone is insufficient",()=>{var(s,u,a)=Start("firedragon","transportship");s.Map.Tiles[a.Path[^1]].terrain=T.Type.Water;Expected(s,u,a,true);});
   Test("intermediate water cannot use alternate land path",()=>{var(s,u,a)=Start("firedragon","rider",2);s.Map.Tiles[a.Path[1]].terrain=T.Type.Water;Expected(s,u,a,true);});
   Test("intermediate native blocked tile",()=>{var(s,u,a)=Start("firedragon","rider",2);s.Map.Tiles[a.Path[1]].Blocked=true;Expected(s,u,a,true);});
   Test("native final endpoint rejection",()=>{var(s,u,a)=Start();s.Map.Tiles[a.Path[0]].Finish=false;Expected(s,u,a,true);});
   foreach(string form in new[]{"island","firedragon"})Test("approved research distinction "+form,()=>{var(s,u,a)=Start("firedragon",form);s.Player.Water=s.Player.Ocean=false;foreach(var t in s.Map.Tiles.Values)t.terrain=T.Type.Water;Expected(s,u,a,form=="island");});
   foreach(bool ocean in new[]{false,true})Test("approved owner shallow/deep unlock "+ocean,()=>{var(s,u,a)=Start("firedragon","island");s.Player.Ocean=ocean;foreach(var t in s.Map.Tiles.Values)t.terrain=T.Type.Ocean;Expected(s,u,a,!ocean);});
   foreach(string alternative in new[]{"bridge","wetland","city"})Test("native water alternative "+alternative,()=>{var(s,u,a)=Start("firedragon","island");s.Player.Water=s.Player.Ocean=false;foreach(var t in s.Map.Tiles.Values){t.terrain=T.Type.Water;if(alternative=="bridge")t.improvement=new(){type=I.Type.Bridge};else if(alternative=="city")t.City=true;else t.Flooded=true;}Expected(s,u,a,false);});
   foreach(string change in new[]{"disabled","unready","unmasked","mimic","wrong-owner","wrong-action-owner","not-queued","invalid","dead","wrong-root","attack","push","empty","single","wrong-start","jump"})Test("ineligible scope "+change,()=>{var(s,u,a)=Start("firedragon","shark");switch(change){case"disabled":NativeRegroupSession.Enabled=false;break;case"unready":s.Ready=false;break;case"unmasked":Change(s,r=>r with{Independent=false,Appearance=null});break;case"mimic":Change(s,r=>r with{Kind=LedgerActualKind.Mimic});break;case"wrong-owner":s.CurrentPlayer=2;break;case"wrong-action-owner":a.PlayerId=2;break;case"not-queued":s.ActionStack.Clear();break;case"invalid":a.Valid=false;break;case"dead":u.health=0;break;case"wrong-root":s.Map.Tiles[u.coordinates].unit=null;break;case"attack":a.Reason=MoveAction.MoveReason.Attack;break;case"push":a.Reason=MoveAction.MoveReason.Push;break;case"empty":a.Path.Clear();break;case"single":a.Path.RemoveAt(0);break;case"wrong-start":a.Path[^1]=new(5,5);break;case"jump":a.Path[0]=new(5,5);break;}
    byte[] bytes=NativeGameStateEnvelope.Get(s)!.Bytes();NativeDisguiseMovement.BeforeMove(a,s,out var scope);Check(scope is null&&!NativeDisguiseMovement.IsShedding(s,u),"ineligible entered scope");Check(NativeGameStateEnvelope.Get(s)!.Bytes().SequenceEqual(bytes),"query mutated ledger");Check(PathFinder.Profiles.Count==0,"ineligible allocated native profile");});
   foreach(string eventKind in new[]{"skip","no-move","throw","clear","map-replaced","turn-changed","owner-changed","root-replaced","mask-replaced"})Test("failed/stale move "+eventKind,()=>{var(s,u,a)=Start("firedragon","shark");var bytes=NativeGameStateEnvelope.Get(s)!.Bytes();switch(eventKind){case"skip":a.Skip=true;break;case"no-move":a.NoMove=true;break;case"throw":a.Throw=true;break;default:a.During=(state,body)=>{switch(eventKind){case"clear":NativeDisguiseMovement.Clear();break;case"map-replaced":state.Map=new();break;case"turn-changed":state.CurrentTurn++;break;case"owner-changed":body.owner=2;break;case"root-replaced":state.Units[1]=new(){id=1};break;case"mask-replaced":Change(state,r=>r with{Appearance=Appearance("rider")});break;}};break;}
    try{a.Execute(s);Check(eventKind!="throw","native exception swallowed");}catch(Exception e){Check(eventKind=="throw"&&e.Message=="native move failed","wrong exception");}Check(Row(s).Independent,"unsuccessful move shed");Check(!NativeDisguiseMovement.IsShedding(s,u),"stale scope leaked");if(eventKind!="mask-replaced")Check(NativeGameStateEnvelope.Get(s)!.Bytes().SequenceEqual(bytes),"unsuccessful ledger changed");});
   foreach(bool realCloak in new[]{false,true})Test("concealment restoration "+realCloak,()=>{var(s,u,a)=Start(realCloak?"cloak":"firedragon","shark");u.effects.Add(UnitEffect.Invisible);u.effects.Add(UnitEffect.Poisoned);var old=u.effects;Expected(s,u,a,true);Check(u.effects.Contains(UnitEffect.Invisible)==realCloak&&u.effects.Contains(UnitEffect.Poisoned),"wrong real concealment policy");Check(old.Contains(UnitEffect.Invisible)&&!ReferenceEquals(old,u.effects),"aliased effects changed");});
   Test("Reveal validation rollback uses real production transaction",()=>{var(s,u,a)=Start("firedragon","shark");u.effects.Add(UnitEffect.Invisible);var old=u.effects;var bytes=NativeGameStateEnvelope.Get(s)!.Bytes();NativeLedgerState.Fail=true;try{a.Execute(s);throw new Exception("expected failure");}catch(InvalidDataException){}Check(ReferenceEquals(old,u.effects)&&NativeGameStateEnvelope.Get(s)!.Bytes().SequenceEqual(bytes),"Reveal rollback lost preimage");Check(NativeRegroupSession.Faults==1&&!NativeDisguiseMovement.IsShedding(s,u),"failure scope/fault");Check(u.coordinates==a.Path[0]&&u.health==70,"must not undo legal native movement");});
   Test("native route exception fails before movement",()=>{var(s,u,a)=Start();PathFinder.ThrowCost=true;var bytes=NativeGameStateEnvelope.Get(s)!.Bytes();try{a.Execute(s);throw new Exception("expected route error");}catch(Exception e){Check(e.Message=="cost failure","native route error lost");}Check(u.coordinates==new WorldCoordinates(0,0)&&NativeGameStateEnvelope.Get(s)!.Bytes().SequenceEqual(bytes)&&NativeRegroupSession.Faults==1,"failed preflight mutated state");});
   Test("duplicate completion is idempotent",()=>{var(s,u,a)=Start("firedragon","shark");NativeDisguiseMovement.BeforeMove(a,s,out var scope);s.Map.Tiles[u.coordinates].unit=null;u.coordinates=a.Path[0];s.Map.Tiles[u.coordinates].unit=u;NativeDisguiseMovement.AfterMove(true,scope);NativeDisguiseMovement.Finished(null,scope);var snap=NativeGameStateEnvelope.Get(s);NativeDisguiseMovement.Finished(null,scope);Check(ReferenceEquals(snap,NativeGameStateEnvelope.Get(s))&&!Row(s).Independent,"duplicate publication");});
   foreach(bool incompatible in new[]{false,true})Test("production terrain bridge "+incompatible,()=>{var(s,u,a)=Start("firedragon","island");s.GameLogicData.Forms["island"].unitAbilities.Add(Polytopia.Data.UnitAbility.Type.AutoFlood);s.Map.Tiles[a.Path[^1]].terrain=T.Type.Water;if(!incompatible)s.Map.Tiles[a.Path[0]].terrain=T.Type.Water;Expected(s,u,a,incompatible);Check(!a.NativeBorrowedFlood,"a compatible or shedding mask cannot supply terrain abilities");});
   Test("production terrain retains actual capability under unrelated mask",()=>{var(s,u,a)=Start("warrior","firedragon");u.UnitData.unitAbilities.Add(Polytopia.Data.UnitAbility.Type.AutoFlood);Expected(s,u,a,false);Check(a.NativeBorrowedFlood,"real underlying native passive remains available under an unrelated mask");});
   Test("nested pending frames restore exact outer scope",()=>{var(s,u,a)=Start("firedragon","shark");var v=new UnitState{id=2,type=U.Type.firedragon,UnitData=u.UnitData,coordinates=new(0,1)};s.Units[2]=v;s.Map.Tiles[v.coordinates]=new(){coordinates=v.coordinates,unit=v};s.Map.Tiles[new(1,1)]=new(){coordinates=new(1,1)};var b=new MoveAction{UnitId=2,Path=new(){new(1,1),new(0,1)}};s.ActionStack.Add(b);var snap=NativeGameStateEnvelope.Get(s)!;var l=NativeIdentityLedgerCodec.Decode(snap.Bytes(),snap.Revision);NativeGameStateEnvelope.Set(s,0,NativeIdentityLedgerCodec.Encode(l with{NextLogicalId=3,Units=new[]{l.Units[0],l.Units[0] with{LogicalId=2,NativeId=2}}},0));NativeDisguiseMovement.BeforeMove(a,s,out var outer);NativeDisguiseMovement.BeforeMove(b,s,out var inner);Check(NativeDisguiseMovement.IsShedding(s,v)&&!NativeDisguiseMovement.IsShedding(s,u),"nested authority not isolated");var error=new Exception("nested native failure");Check(ReferenceEquals(NativeDisguiseMovement.Finished(error,inner),error)&&NativeDisguiseMovement.IsShedding(s,u),"outer scope or native exception lost");NativeDisguiseMovement.Finished(null,outer);Check(!NativeDisguiseMovement.IsShedding(s,u)&&Row(s).Independent,"unfinished outer move mutated");});
   Test("pending is exact state and unit",()=>{var(s,u,a)=Start("firedragon","shark");NativeDisguiseMovement.BeforeMove(a,s,out var scope);Check(NativeDisguiseMovement.IsShedding(s,u)&&!NativeDisguiseMovement.IsShedding(new GameState(),u)&&!NativeDisguiseMovement.IsShedding(s,new UnitState()),"passive guard leaks scope");NativeDisguiseMovement.Finished(null,scope);});
   Console.WriteLine(JsonSerializer.Serialize(new{passed=true,cases=Cases,assertions=Assertions,nativeGame="NOT RUN"}));return 0;
  }catch(Exception e){Console.WriteLine(e);return 1;}}
 }
}
